import {
  REFERENCE_RAMP_MAX_HUE
} from "./chunk-RX5CSWJW.js";

// src/referenceRampCss.ts
function rampHueCss(hue) {
  return `hsl(${hue}, 70%, 50%)`;
}
function rampHue(bp, domain) {
  const frac = (bp - domain.start) / (domain.end - domain.start);
  return Math.max(0, Math.min(1, frac)) * REFERENCE_RAMP_MAX_HUE;
}
var HUE_STOP_DEG = 30;
function rampStops({ start, bp, reversed }, domain) {
  const low = rampHue(start, domain);
  const high = rampHue(start + bp, domain);
  if (high - low < 1) {
    return [(low + high) / 2];
  }
  const n = Math.ceil((high - low) / HUE_STOP_DEG);
  return Array.from(
    { length: n + 1 },
    (_, i) => rampHue(start + bp * (reversed ? n - i : i) / n, domain)
  );
}
var RAMP_GRADIENT_STOPS = Array.from({ length: 7 }, (_, i) => ({
  offset: i / 6,
  color: rampHueCss(i / 6 * REFERENCE_RAMP_MAX_HUE)
}));
var RAMP_GRADIENT_CSS = `linear-gradient(to right, ${RAMP_GRADIENT_STOPS.map(
  (s) => `${s.color} ${s.offset * 100}%`
).join(", ")})`;

export {
  rampHueCss,
  rampHue,
  rampStops,
  RAMP_GRADIENT_STOPS,
  RAMP_GRADIENT_CSS
};
